    for(int s=0;s<k;s++){ x+=dx[d]; y+=dy[d]; dist++;
      if(x<0||x>W||y<0||y>D||seen.count({x,y})){ printf("%d\n(%d,%d) D\n",dist,x,y); return 0; } seen.insert({x,y}); } }
  printf("%d\n(%d,%d) A\n",dist,x,y); }

